mapper.select:
SELECT TO_CHAR(tdm50_start_date, 'yyyy-mm-dd')
  FROM tdm50_chck_job
 WHERE tdm50_chck_job_id = #{chckJobId}

mapper.update:
UPDATE tdm52_chck_manl
   SET tdm52_check_status_cd = CAST(#{checkStatusCode} AS varchar)
     , tdm52_upd_nm          = #{updName}
     , tdm52_upd_date        = f_sysdate()
 WHERE tdm52_chck_org_id     = #{chckOrgId}

mapper.select:
SELECT tdm52_chck_manl_id
  FROM tdm52_chck_manl
 WHERE tdm52_chck_org_id     = #{chckOrgId}
   AND tdm52_check_status_cd = #{checkStatusCode}

mapper.update:
UPDATE tdm52_chck_manl
   SET tdm52_check_status_cd = #{checkStatusCode}
     , tdm52_upd_nm          = #{updName}
     , tdm52_upd_date        = f_sysdate()
 WHERE tdm52_chck_manl_id    = #{chckManlId}

UPDATE tdm59_chck_appr_cmnt
   SET tdm59_appr_status_cd    = CAST(#{apprStatusCode} AS varchar)
 WHERE tdm59_chck_appr_cmnt_id = #{chckApprCmntId}

UPDATE tdm54_chck_insuff
   SET tdm54_status_cd      = #{statusCode}
     , tdm54_action_appr_ym = CAST(#{actionApprYm} AS varchar)
     , tdm54_upd_nm         = #{updName}
 WHERE tdm54_chck_insuff_id = #{chckInsuffId}
